styleText:
/* ─── Reset & Base ─── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg:         #F7F7F4;
      --white:      #FFFFFF;
      --accent:     #CDB18B;
      --accent-dim: #F2E4CF;
      --dark:       #0D1117;
      --dark-2:     #1A1F2E;
      --dark-3:     #0F1520;
      --text:       #111111;
      --muted:      #6B7280;
      --muted-2:    #9CA3AF;
      --border:     rgba(0,0,0,0.07);
      --border-2:   rgba(0,0,0,0.12);
      --shadow-xs:  0 1px 3px rgba(0,0,0,0.05);
      --shadow-sm:  0 2px 10px rgba(0,0,0,0.06);
      --shadow-md:  0 8px 32px rgba(0,0,0,0.08);
      --shadow-lg:  0 20px 60px rgba(0,0,0,0.10);
      --shadow-xl:  0 40px 100px rgba(0,0,0,0.12);
      --radius-sm:  10px;
      --radius-md:  16px;
      --radius-lg:  24px;
      --radius-xl:  32px;
      --radius-full:9999px;
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
    a { text-decoration: none; color: inherit; }

    /* ─── Animations ─── */
    @keyframes fadeInUp { from { opacity:0; transform:translateY(24px);} to { opacity:1; transform:translateY(0);} }
    @keyframes pulse-dot { 0%,100%{opacity:1;transform:scale(1);} 50%{opacity:.5;transform:scale(.85);} }
    @keyframes flow-down { 0%{opacity:0;transform:translateY(-8px);} 50%{opacity:1;} 100%{opacity:0;transform:translateY(18px);} }
    @keyframes marquee { 0%{transform:translateX(0);} 100%{transform:translateX(-50%);} }


    .fade-in-up { animation: fadeInUp 0.7s cubic-bezier(.22,1,.36,1) both; }
    .d1{animation-delay:.1s;} .d2{animation-delay:.2s;} .d3{animation-delay:.3s;} .d4{animation-delay:.4s;}

    /* ─── Layout ─── */
    .container { width:100%; max-width:1200px; margin:0 auto; padding:0 32px; }
    .section { padding:100px 0; }
    .section-sm { padding:64px 0; }
    .eyebrow {
      display:inline-flex; align-items:center; gap:7px;
      font-size:11px; font-weight:600; letter-spacing:.12em;
      text-transform:uppercase; color:var(--muted); margin-bottom:18px;
    }
    .eyebrow-dot { width:6px;height:6px;border-radius:50%;background:var(--accent);animation:pulse-dot 2s ease infinite; }
    .eyebrow-light { color:rgba(255,255,255,0.45); }
    .eyebrow-light .eyebrow-dot { background:var(--accent); }
    .section-headline { font-size:clamp(30px,4vw,46px);font-weight:800;line-height:1.1;letter-spacing:-.025em;margin-bottom:14px; }
    .section-sub { font-size:16px;color:var(--muted);max-width:480px;line-height:1.7; }

    /* ─── Buttons ─── */
    .btn { display:inline-flex;align-items:center;gap:8px;border-radius:var(--radius-full);font-family:'Inter',sans-serif;font-weight:600;font-size:14px;cursor:pointer;transition:all .2s cubic-bezier(.22,1,.36,1);border:none;white-space:nowrap; }
    .btn-primary { background:var(--dark);color:#fff;padding:13px 28px;box-shadow:0 2px 8px rgba(0,0,0,.15); }
    .btn-primary:hover { background:var(--dark-2);transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.2); }
    .btn-accent  { background:var(--accent);color:var(--dark);padding:13px 28px;box-shadow:0 2px 8px rgba(205,177,139,.3); }
    .btn-accent:hover { background:#dac09e;transform:translateY(-2px);box-shadow:0 8px 24px rgba(205,177,139,.4); }
    .btn-outline { background:transparent;color:var(--text);padding:12px 24px;border:1.5px solid var(--border-2); }
    .btn-outline:hover { background:var(--white);color:#0D1117 !important;transform:translateY(-1px);box-shadow:var(--shadow-sm); }
    .btn-outline-light { background:transparent;color:rgba(255,255,255,.75);padding:12px 24px;border:1.5px solid rgba(255,255,255,.2); }
    .btn-outline-light:hover { background:rgba(255,255,255,.08); }

    /* ══════════════ NAVBAR ══════════════ */
    .navbar {
      position:fixed;top:0;left:0;right:0;z-index:1000;
      padding:0 40px;height:64px;
      display:flex;align-items:center;justify-content:space-between;
      background:rgba(247,247,244,.82);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);
      border-bottom:1px solid var(--border);
    }
    .nav-logo { display:flex;align-items:center;gap:9px;font-weight:800;font-size:18px;letter-spacing:-.03em; }
    .nav-logo-icon { width:30px;height:30px;background:var(--dark);border-radius:8px;display:flex;align-items:center;justify-content:center; }
    .nav-logo-icon svg { width:16px;height:16px; }
    .nav-links { display:flex;align-items:center;gap:2px;list-style:none; }
    .nav-links a { font-size:13px;font-weight:500;color:var(--muted);padding:7px 11px;border-radius:var(--radius-full);transition:all .15s;display:flex;align-items:center;gap:3px;white-space:nowrap; }
    .nav-links a:hover { color:var(--text);background:rgba(0,0,0,.04); }
    .nav-links a.active { color:var(--text);font-weight:600;background:rgba(0,0,0,.06); }
    .nav-actions { display:flex;align-items:center;gap:10px; }

    /* Mega Menu */
    .nav-item { position:relative;list-style:none; }
    .nav-chevron { font-size:9px;opacity:.45;transition:transform .18s;line-height:1; }
    .nav-item.has-mega:hover .nav-chevron,
    .nav-item.has-mega.mega-open .nav-chevron { transform:rotate(180deg);opacity:.7; }
    .mega-panel {
      position:fixed;top:64px;left:50%;
      transform:translateX(-50%) translateY(-6px);
      background:var(--white);border:1px solid var(--border-2);border-radius:var(--radius-lg);
      box-shadow:0 8px 16px rgba(0,0,0,.06),0 24px 64px rgba(0,0,0,.10);
      padding:24px;opacity:0;pointer-events:none;
      transition:opacity .18s ease,transform .18s ease;z-index:999;
    }
    .nav-item.has-mega:hover .mega-panel,
    .nav-item.has-mega.mega-open .mega-panel {
      opacity: 1;
      pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }
    .mega-products  { width:1040px; }
    .mega-solutions { width:680px; }
    .mega-platform  { width:680px; }
    /* Thin top accent bar */
    .mega-panel::before { content:'';position:absolute;top:0;left:24px;right:24px;height:2px;background:var(--accent);border-radius:0 0 2px 2px;opacity:.6; }
    /* Transparent hover bridge — prevents gap closing the menu */
    .mega-panel::after {
      content: '';
      position: absolute;
      top: -18px; left: 0; right: 0;
      height: 18px;
    }

    /* Hightouch-style column mega */
    .mega-cols { display:flex; align-items:flex-start; gap:0; }
    .mega-col {
      flex:1; padding:0 28px;
      border-right:1px solid var(--border-2);
      min-width:0;
    }
    .mega-col:first-child { padding-left:0; }
    .mega-col:last-child  { border-right:none; }

    .mega-col-label {
      font-size:10px; font-weight:700; letter-spacing:.1em;
      text-transform:uppercase; color:var(--muted);
      margin-bottom:16px; padding-bottom:12px;
      border-bottom:1px solid var(--border-2);
      white-space:nowrap;
    }
    .mega-col-link {
      display:block; font-size:14px; color:var(--text);
      text-decoration:none; padding:7px 0; font-weight:500;
      transition:color .15s; white-space:nowrap;
    }
    .mega-col-link:hover { color:var(--accent); }

    .mega-col-badge {
      font-size:9px; font-weight:700; letter-spacing:.05em;
      text-transform:uppercase; color:var(--accent);
      background:rgba(205,177,139,.15); border-radius:3px;
      padding:2px 5px; margin-left:6px; vertical-align:middle;
    }

    /* Featured column */
    .mega-col-featured { flex:0 0 200px !important; padding:0 0 0 28px !important; border-right:none !important; }
    .mega-featured-img {
      width:100%; height:110px; border-radius:var(--radius-sm);
      overflow:hidden; margin-bottom:12px;
    }
    .mega-featured-img img { width:100%; height:100%; object-fit:cover; }
    .mega-featured-desc {
      font-size:12.5px; color:var(--muted); line-height:1.65; margin-bottom:12px;
    }
    .mega-featured-link {
      font-size:12.5px; font-weight:600; color:var(--text);
      text-decoration:none; display:flex; align-items:center; gap:4px;
    }
    .mega-featured-link:hover { color:var(--accent); }

    /* ══════════════ PLATFORM HERO ══════════════ */
    .plat-hero {
      position:relative;overflow:hidden;
      text-align:center;
    }
    .plat-hero-bg {
      position:relative;z-index:0;
    }
    .plat-hero-bg img {
      width:100%;height:auto;display:block;
      transform:translateY(-6%);
      margin-bottom:-6%;
    }
    .plat-hero-content-wrap {
      position:absolute;inset:0;z-index:2;
      display:flex;align-items:flex-start;justify-content:center;
      padding-top:160px;
    }
    .plat-hero-glow {
      position:absolute;top:50%;left:50%;
      transform:translate(-50%,-50%);
      width:700px;height:400px;
      background:radial-gradient(ellipse at center,rgba(205,177,139,.10) 0%,transparent 70%);
      pointer-events:none;z-index:1;
    }
    .plat-hero-glow-2 { display:none; }
    .plat-hero-content { position:relative;z-index:1;max-width:760px;margin:0 auto;text-align:center;display:flex;flex-direction:column;align-items:center; }
    .plat-hero h1 {
      font-size:clamp(32px,4.5vw,56px);font-weight:900;line-height:1.04;
      letter-spacing:-.04em;color:var(--text);margin-bottom:18px;
    }
    .plat-hero h1 em { font-style:italic;font-family:'DM Serif Display',serif;font-weight:400;color:var(--text); } h2 em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; } .section-headline em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; }
    .plat-hero p { font-size:18px;color:var(--muted);max-width:520px;margin:0 auto 36px;line-height:1.75; }
    .plat-hero-ctas { display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap; }
    .eyebrow-light { color:var(--muted) !important; }
    .eyebrow-light .eyebrow-dot { background:var(--accent) !important; }
    /* Floating arch chips above fold */
    .plat-hero-chips {
      display:flex;align-items:center;justify-content:center;gap:10px;
      flex-wrap:wrap;margin-bottom:40px;
    }
    .hero-chip {
      display:inline-flex;align-items:center;gap:7px;
      background:rgba(255,255,255,.55);border:1px solid rgba(0,0,0,.08);
      border-radius:var(--radius-full);padding:6px 14px;
      font-size:12px;font-weight:500;color:var(--text);
      backdrop-filter:blur(8px);
    }
    .hero-chip-dot { width:6px;height:6px;border-radius:50%;flex-shrink:0; }

    /* ══════════════ WHAT IS SECTION ══════════════ */
    .what-section { background:var(--bg); }
    .what-header { display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start;margin-bottom:56px; }
    .what-grid { display:grid;grid-template-columns:repeat(3,1fr);gap:20px; }
    .what-card {
      background:var(--white);border:1px solid var(--border);
      border-radius:var(--radius-lg);padding:32px;
      transition:all .25s cubic-bezier(.22,1,.36,1);
      position:relative;overflow:hidden;
    }
    .what-card:hover { box-shadow:var(--shadow-lg);transform:translateY(-3px); }
    .what-card-num {
      font-size:11px;font-weight:700;letter-spacing:.08em;
      text-transform:uppercase;color:var(--accent);margin-bottom:20px;
      display:flex;align-items:center;gap:8px;
    }
    .what-card-num::after { content:'';flex:1;height:1px;background:var(--accent-dim); }
    .what-card-icon {
      width:48px;height:48px;border-radius:14px;
      background:var(--bg);border:1px solid var(--border);
      display:flex;align-items:center;justify-content:center;
      font-size:22px;margin-bottom:18px;
    }
    .what-card-title { font-size:18px;font-weight:800;letter-spacing:-.02em;margin-bottom:10px; }
    .what-card-desc { font-size:13.5px;color:var(--muted);line-height:1.7; }
    .what-card-tag {
      display:inline-flex;margin-top:18px;
      font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;
      background:var(--accent-dim);color:#8A6B40;
      padding:4px 10px;border-radius:var(--radius-full);
    }
    /* accent card */
    .what-card.accent { background:var(--dark);border-color:var(--dark);color:#fff; }
    .what-card.accent .what-card-title { color:#fff; }
    .what-card.accent .what-card-desc { color:rgba(255,255,255,.55); }
    .what-card.accent .what-card-icon { background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.1); }

    /* ══════════════ ARCHITECTURE LAYERS ══════════════ */
    .arch-section {
      padding:100px 0;
      position:relative;overflow:hidden;
    }
    .arch-section-bg {
      position:absolute;inset:0;z-index:0;
    }
    .arch-section-bg img {
      width:100%;height:100%;object-fit:cover;object-position:center center;
    }
    .arch-section > .container { position:relative;z-index:1; }
    .arch-header { text-align:center;margin-bottom:64px; }
    .arch-header .section-headline { color:var(--text);text-shadow:0 1px 8px rgba(255,255,255,.6); }
    .arch-header .section-sub { color:var(--text);margin:0 auto;text-shadow:0 1px 6px rgba(255,255,255,.5); }
    .arch-section .eyebrow-light { color:var(--text) !important; }

    /* Stack container */
    .arch-stack { max-width:920px;margin:0 auto;position:relative; }

    /* layer card */
    .layer-card {
      border-radius:var(--radius-lg);padding:28px 32px;
      border:1px solid rgba(0,0,0,.08);
      background:rgba(255,255,255,.88);
      backdrop-filter:blur(12px);
      position:relative;overflow:hidden;
      transition:all .2s;
      box-shadow:0 2px 20px rgba(0,0,0,.06);
    }
    .layer-card:hover { transform:translateY(-2px);box-shadow:0 6px 28px rgba(0,0,0,.1); }
    .layer-card-inner { display:grid;grid-template-columns:200px 1fr;gap:28px;align-items:center; }
    .layer-meta {}
    .layer-num {
      font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
      margin-bottom:8px;display:flex;align-items:center;gap:6px;
    }
    .layer-num-badge {
      width:20px;height:20px;border-radius:6px;
      display:flex;align-items:center;justify-content:center;
      font-size:10px;font-weight:800;
    }
    .layer-title { font-size:17px;font-weight:800;color:var(--text);letter-spacing:-.02em;margin-bottom:6px; }
    .layer-desc { font-size:12px;color:var(--muted);line-height:1.5; }
    .layer-chips { display:flex;flex-wrap:wrap;gap:8px; }
    .l-chip {
      display:inline-flex;align-items:center;gap:7px;
      border-radius:var(--radius-sm);padding:9px 13px;
      font-size:12px;font-weight:600;
      border:1px solid;transition:all .15s;cursor:default;
    }
    .l-chip-icon { font-size:14px; }

    /* Layer color themes */
    .layer-exp  .layer-num  { color:#8a6a3a; }
    .layer-exp  .layer-num-badge { background:rgba(205,177,139,.25);color:#8a6a3a; }
    .layer-exp  .l-chip { background:rgba(205,177,139,.18);border-color:rgba(205,177,139,.4);color:var(--text); }
    .layer-exp  .l-chip:hover { background:rgba(205,177,139,.32); }

    .layer-app  .layer-num  { color:#3a5fa0; }
    .layer-app  .layer-num-badge { background:rgba(99,130,200,.2);color:#3a5fa0; }
    .layer-app  .l-chip { background:rgba(99,130,200,.12);border-color:rgba(99,130,200,.35);color:var(--text); }
    .layer-app  .l-chip:hover { background:rgba(99,130,200,.22); }

    .layer-svc  .layer-num  { color:#1e7a53; }
    .layer-svc  .layer-num-badge { background:rgba(52,168,120,.2);color:#1e7a53; }
    .layer-svc  .l-chip { background:rgba(52,168,120,.12);border-color:rgba(52,168,120,.35);color:var(--text); }
    .layer-svc  .l-chip:hover { background:rgba(52,168,120,.22); }

    .layer-ai   .layer-num  { color:#6b3fd4; }
    .layer-ai   .layer-num-badge { background:rgba(139,92,246,.2);color:#6b3fd4; }
    .layer-ai   .l-chip { background:rgba(139,92,246,.12);border-color:rgba(139,92,246,.35);color:var(--text); }
    .layer-ai   .l-chip:hover { background:rgba(139,92,246,.22); }

    /* Connector between layers */
    .layer-connector {
      display:flex;flex-direction:column;align-items:center;
      padding:6px 0;gap:2px;
    }
    .conn-line {
      width:1px;height:20px;
      background:linear-gradient(to bottom,rgba(0,0,0,.15),rgba(0,0,0,.05));
      position:relative;overflow:hidden;
    }
    .conn-line::after {
      content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
      width:3px;height:8px;border-radius:2px;background:var(--accent);opacity:.7;
      animation:flow-down 1.8s ease infinite;
    }
    .conn-arrow { font-size:10px;color:rgba(0,0,0,.25); }
    .conn-label { font-size:9px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:rgba(0,0,0,.3); }

    /* Shared services sub-grid */
    .svc-chips-grid { display:grid;grid-template-columns:repeat(2,1fr);gap:8px; }

    /* ══════════════ WHY BETTER ══════════════ */
    .why-section { background: #FFFFFF; }
    .why-header { text-align:center;margin-bottom:56px; }
    .why-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; align-items: start; }
    .why-card {
      position: relative;
      display: flex;
      flex-direction: column;
      padding: 28px 26px;
      border-radius: var(--radius-lg);
      background: #F7F7F4;
      color: var(--dark);
      border: 1px solid rgba(13,17,23,0.08);
      overflow: hidden;
      transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
    }
    .why-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 18px 38px rgba(13,17,23,0.10);
      border-color: rgba(13,17,23,0.16);
    }
    .why-card-body {
      flex: 0 0 auto;
      max-width: 92%;
    }
    .why-metric { font-size:48px;font-weight:900;letter-spacing:-.04em;line-height:1;margin-bottom:8px; }
    .why-card-title {
      font-size: 22px;
      font-weight: 800;
      letter-spacing: -.02em;
      line-height: 1.18;
      margin-bottom: 12px;
      color: var(--dark);
    }
    .why-card-desc {
      font-size: 13.5px;
      line-height: 1.65;
      color: var(--muted);
    }

    .why-card-art {
      position: relative;
      flex: 0 0 auto;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 18px -10px 0;
      color: var(--accent);
    }
    .why-card-art svg { width: 100%; height: auto; max-width: 280px; display: block; }
    .why-card-foot {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-top: auto;
    }
    .why-card-tag {
      display: inline-flex;
      align-items: center;
      padding: 8px 14px;
      border-radius: 999px;
      background: #FFFFFF;
      border: 1px solid rgba(13,17,23,0.10);
      font-size: 12.5px;
      font-weight: 600;
      color: #0D1117 !important;
      letter-spacing: 0.01em;
    }
    .why-card-arrow {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 36px;
      height: 36px;
      border-radius: 999px;
      background: var(--dark);
      color: var(--accent);
      transition: transform .25s ease, background .25s ease;
    }
    .why-card-arrow .material-symbols-rounded { font-size: 20px; }
    .why-card:hover .why-card-arrow { transform: translateX(3px); background: var(--accent); color: var(--dark); }

    /* === CARD 1 === */
    .why-card .art1-app { transform-origin: center; transform-box: fill-box; }
    .why-card .art1-app-a { animation: app1Float 5s ease-in-out infinite; }
    .why-card .art1-app-b { animation: app1Float 5s ease-in-out 1.6s infinite; }
    .why-card .art1-app-c { animation: app1Float 5s ease-in-out 0.8s infinite; }
    @keyframes app1Float {
      0%, 100% { transform: translateY(0); }
      50%      { transform: translateY(-3px); }
    }
    .why-card .art1-feed {
      stroke-dashoffset: 0;
      animation: feedFlow 1.6s linear infinite;
    }
    .why-card .art1-feed-b { animation-delay: 0.4s; }
    .why-card .art1-feed-c { animation-delay: 0.8s; }
    @keyframes feedFlow { to { stroke-dashoffset: -18; } }
    .why-card .art1-packet {
      transform-origin: center;
      transform-box: fill-box;
      animation: packet1A 2.4s cubic-bezier(.4,0,.6,1) infinite;
    }
    .why-card .art1-packet-b { animation: packet1B 2.4s cubic-bezier(.4,0,.6,1) 0.6s infinite; }
    .why-card .art1-packet-c { animation: packet1C 2.4s cubic-bezier(.4,0,.6,1) 1.2s infinite; }
    @keyframes packet1A {
      0%   { transform: translate(0,0);    opacity: 0; }
      12%  { opacity: 1; }
      60%  { transform: translate(38px, 22px); opacity: 1; }
