(function() {
    document.querySelectorAll('.nav-item.has-mega').forEach(function(item) {
      var panel = item.querySelector('.mega-panel');
      var timer;
      function openMenu()  { clearTimeout(timer); item.classList.add('mega-open'); }
      function closeMenu() { timer = setTimeout(function() { item.classList.remove('mega-open'); }, 120); }
      item.addEventListener('mouseenter', openMenu);
      item.addEventListener('mouseleave', closeMenu);
      if (panel) {
        panel.addEventListener('mouseenter', openMenu);
        panel.addEventListener('mouseleave', closeMenu);
      }
    });
  })();

(function() {
  var wrapper = document.getElementById('prod-scroll-wrapper');
  var section = document.getElementById('prod-scroll-section');
  var rail    = document.getElementById('prod-h-rail');
  var bar     = document.getElementById('prod-h-bar');
  var counter = document.getElementById('prod-h-counter');
  if (!wrapper || !rail) return;

  if (window.matchMedia && window.matchMedia('(max-width: 768px)').matches) {
    wrapper.style.height = '';
    rail.style.transform = '';
    return;
  }

  var CARDS      = 11;
  var curX       = 0;
  var maxTravel  = 0;

  function getProgress() {
    var rect       = wrapper.getBoundingClientRect();
    var scrollable = wrapper.offsetHeight - window.innerHeight;
    if (scrollable <= 0) return 0;
    return Math.max(0, Math.min(1, -rect.top / scrollable));
  }

  function setWrapperHeight() {
    /* travel = how far the rail must slide: rail width minus visible viewport width */
    maxTravel = rail.scrollWidth - window.innerWidth;
    if (maxTravel < 0) maxTravel = 0;
    /* wrapper height = sticky section height + horizontal travel distance */
    wrapper.style.height = 'calc(100vh + ' + maxTravel + 'px)';
  }

  function lerp(a, b, t) { return a + (b - a) * t; }

  function tick() {
    requestAnimationFrame(tick);
    var progress = getProgress();
    var targetX  = -progress * maxTravel;

    curX = lerp(curX, targetX, 0.12);
    rail.style.transform = 'translateX(' + curX + 'px)';

    /* progress bar */
    if (bar) bar.style.width = (progress * 100).toFixed(1) + '%';

    /* card counter */
    if (counter) {
      var idx = Math.min(CARDS - 1, Math.floor(progress * CARDS));
      counter.textContent = (idx + 1) + ' / ' + CARDS;
    }
  }

  function init() {
    setWrapperHeight();
    tick();
  }

  window.addEventListener('resize', setWrapperHeight);

  /* wait one frame for layout to settle */
  requestAnimationFrame(function() { requestAnimationFrame(init); });
})();

function toggleFaq(el) {
    var item = el.parentElement;
    var icon = el.querySelector('.faq-icon');
    var isOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(function(i) {
      i.classList.remove('open');
      i.querySelector('.faq-icon').textContent = '+';
    });
    if (!isOpen) { item.classList.add('open'); icon.textContent = '−'; }
  }
